/* v0.43: adapter for existing v0.42 ecology. World coordinates are screen-projected units. */
const CW=72,CH=50,W=480,H=320,cl=(v,a,b)=>Math.max(a,Math.min(b,v));
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
let s,p,keys=new Set(),action=null,clock=0,auto=true,run=false,last=0,cam={x:0,y:0},loaded=false,notice='',steps=0;
const sprites={};const terrain=new Image();terrain.src=ART.ground;for(const [id,src] of Object.entries(ART.images)){const im=new Image();im.src=src;sprites[id]=im}
function cell(x,y){return s.cells[cl(Math.floor(y/CH),0,Eco.H-1)*Eco.W+cl(Math.floor(x/CW),0,Eco.W-1)]}
function isWater(c){return c.channel&&c.surface>1}
function newWorld(seed=42){s=Aquatic.create(seed);const c=s.cells.find(c=>c.kind==='valley'&&!c.channel&&c.y>=12&&c.x>=8);p={x:(c.x+.5)*CW,y:(c.y+.5)*CH,dir:'down',f:0,t:0,energy:100,water:100,food:100,bag:{fruit:0},distance:0};clock=0;steps=0;action=null;keys.clear();notice='Explore a ilha experimental.';refresh()}
function target(){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[p.dir];return cell(p.x+d[0]*CW*.65,p.y+d[1]*CH*.65)}
function perform(kind){if(action||isWater(cell(p.x,p.y)))return false;const c=target();if(c.channel){notice='Escolha um terreno em terra firme.';refresh();return false}if(p.energy<3){notice='Descanse antes de trabalhar.';refresh();return false}const map={axe:'cut',sickle:'cut',water:'water',harvest:'harvest',seed:'seed:'+Number($('seed').value)};const edit=map[kind];if(!edit)return false;action={kind,edit,index:c.y*Eco.W+c.x,time:0,committed:false};keys.clear();p.f=0;return true}
function commit(){if(!action||action.committed)return;action.committed=true;const c=s.cells[action.index],fruit=c.fruit;let ok=Aquatic.landEdit(s,action.index,action.edit);if(ok){p.energy=Math.max(0,p.energy-3);if(action.kind==='harvest')p.bag.fruit+=fruit;notice=({axe:'Vegetação removida; resíduos retornam ao solo.',sickle:'Vegetação cortada; resíduos retornam ao solo.',water:'Água adicionada ao terreno.',harvest:'Frutos retirados do ecossistema.',seed:'Propágulos introduzidos no solo.'})[action.kind]}else notice='Ação indisponível neste terreno ou fase vegetal.';refresh()}
function advance(n=1){for(let i=0;i<n;i++){Aquatic.tick(s);steps++;p.food=cl(p.food-.7,0,100);p.water=cl(p.water-(s.temp>30?1.4:.8),0,100);p.energy=cl(p.energy-.45,0,100)}refresh()}
function rest(){if(action||isWater(cell(p.x,p.y)))return;advance(1);p.energy=cl(p.energy+23,0,100);notice='Repouso de seis horas.';refresh()}
function eat(){if(p.bag.fruit<.001){notice='Nenhum fruto colhido.';refresh();return}let q=Math.min(p.bag.fruit,.02);p.bag.fruit-=q;p.food=cl(p.food+20*q/.02,0,100);notice='Fruta consumida (inventário experimental).';refresh()}
function drink(){if(![cell(p.x,p.y),target()].some(isWater)){notice='Aproxime-se do rio.';refresh();return}notice='Água do rio não tratada: consumo bloqueado neste protótipo.';refresh()}
function save(){try{localStorage.setItem('iv043_field',JSON.stringify({version:43,s,p,steps}));notice='Partida salva localmente.'}catch(e){notice='Armazenamento indisponível.'}refresh()}
function load(){try{const z=JSON.parse(localStorage.getItem('iv043_field'));if(z.version!==43||z.s.version!==42||z.s.cells.length!==1120||!Number.isFinite(z.p.x)||!Number.isFinite(z.p.y))throw Error();s=z.s;p=z.p;steps=z.steps;action=null;keys.clear();clock=0;notice='Partida restaurada.'}catch(e){notice='Nenhum salvamento compatível.'}refresh()}
function refresh(){if(!s||!p)return;const c=target();$('day').textContent=`Dia ${Math.floor(s.day)+1} • ${String((s.step%4)*6).padStart(2,'0')}:00`;$('clim').textContent=`${s.temp.toFixed(1)} °C · chuva ${s.rain.toFixed(1)}`;$('needs').textContent=`Energia ${Math.round(p.energy)}% · Fome ${Math.round(100-p.food)}% · Sede ${Math.round(100-p.water)}%`;$('info').textContent=`${c.channel?'Rio':Eco.types[c.kind].name} · ${Flora.species[c.sp]?.name||'Sem vegetação'} · Umidade ${Math.round(c.water/c.cap*100)}% · Fósforo ${c.soilP.toFixed(3)} · ${c.phase||'água'}`;$('log').textContent=notice;$('bag').textContent=`Frutos: ${p.bag.fruit.toFixed(3)} un. de biomassa · Fauna terrestre: ${s.animals.length} · Insetos: ${s.insects.length}`;$('mode').textContent=auto?'Tempo: automático':'Tempo: pausado';$('run').textContent=run?'Corrida':'Caminhada'}
function move(dt){if(action){action.time+=dt;if(action.time>=.52)commit();if(action.time>=1){action=null;p.t=0}return}let dx=+keys.has('right')-+keys.has('left'),dy=+keys.has('down')-+keys.has('up');if(!dx&&!dy){p.t=0;return}if(Math.abs(dx)>0)p.dir=dx>0?'right':'left';else p.dir=dy>0?'down':'up';let norm=Math.hypot(dx,dy),wet=isWater(cell(p.x,p.y)),speed=wet?62:run&&p.energy>0?145:88;let x=cl(p.x+dx/norm*speed*dt,5,Eco.W*CW-5),y=cl(p.y+dy/norm*speed*dt,5,Eco.H*CH-5);p.distance+=Math.hypot(x-p.x,y-p.y);p.x=x;p.y=y;p.t+=dt;if(run&&!wet)p.energy=cl(p.energy-dt*.65,0,100)}
function hash(a,b){return ((Math.imul(a+17,374761393)^Math.imul(b+3,668265263))>>>0)%997/997}
function draw(){cam.x=cl(p.x-W/2,0,Eco.W*CW-W);cam.y=cl(p.y-H/2,0,Eco.H*CH-H);ctx.clearRect(0,0,W,H);const x0=Math.max(0,Math.floor(cam.x/CW)-1),x1=Math.min(Eco.W-1,Math.floor((cam.x+W)/CW)+1),y0=Math.max(0,Math.floor(cam.y/CH)-1),y1=Math.min(Eco.H-1,Math.floor((cam.y+H)/CH)+1);const objects=[];
for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const c=s.cells[y*Eco.W+x],px=Math.floor(x*CW-cam.x),py=Math.floor(y*CH-cam.y);const col=c.kind==='humid'?'#405f37':c.kind==='dry'?'#8e7950':'#71834a';ctx.fillStyle=col;ctx.fillRect(px,py,CW,CH);if(isWater(c)){ctx.fillStyle='#397b86';ctx.fillRect(px,py,CW,CH);ctx.fillStyle='#75a6a4';for(let i=0;i<6;i++){let v=hash(x*9+i,y);ctx.fillRect(px+v*60,py+hash(y*11+i,x)*44,9,1)}continue}if(terrain.complete&&terrain.naturalWidth){let tx=c.b>.22?0:2;ctx.globalAlpha=.68;ctx.drawImage(terrain,(Math.floor(hash(x,y)*4))*64,tx*64,64,64,px,py,CW,CH);ctx.globalAlpha=1}if(c.water/c.cap<.18){ctx.fillStyle='#9b734340';ctx.fillRect(px,py,CW,CH)}if(c.surface>3){ctx.fillStyle='#397b8650';ctx.fillRect(px,py,CW,CH)}for(let i=0;i<9;i++){let a=hash(x*13+i,y),b=hash(y*17+i,x);ctx.fillStyle=i%2?'#b7b36b45':'#263d2950';ctx.fillRect(px+a*CW,py+b*CH,2+i%3,2)}if(c.sp>=0&&c.b>.16){const gx=px+CW*(.3+.4*hash(x,y)),gy=py+CH*(.4+.4*hash(y,x));objects.push({y:gy,draw:()=>plant(c,gx,gy)})}}
const t=target();ctx.strokeStyle='#eed49d';ctx.setLineDash([3,4]);ctx.strokeRect(t.x*CW-cam.x+2,t.y*CH-cam.y+2,CW-4,CH-4);ctx.setLineDash([]);
for(const a of s.animals){const c=s.cells[a.pos];let x=(c.x+.25+.5*hash(a.id,1))*CW-cam.x,y=(c.y+.3+.5*hash(a.id,2))*CH-cam.y;if(x<-20||x>W+20||y<-20||y>H+20)continue;objects.push({y,draw:()=>{ctx.fillStyle='#14241f';ctx.beginPath();ctx.ellipse(x,y,6,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=Vertebrates.P[a.sp].color;ctx.fillRect(x-3,y-4,6,5);ctx.fillStyle='#f5e9c9';ctx.font='8px system-ui';ctx.fillText(Vertebrates.P[a.sp].name.split(' ')[0],x+6,y-4)}})}objects.push({y:p.y-cam.y,draw:hero});objects.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());if(s.rain>4){ctx.strokeStyle='#c1dfe750';ctx.lineWidth=1;for(let i=0;i<30;i++){const x=(hash(i,8)*W+performance.now()*.035)%W,y=(hash(i,9)*H+performance.now()*.16)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+9);ctx.stroke()}}if(s.step%4===0){ctx.fillStyle='#14294a40';ctx.fillRect(0,0,W,H)}}
function plant(c,x,y){const size=cl(c.b,.16,1);ctx.fillStyle='#182f263e';ctx.beginPath();ctx.ellipse(x,y,12*size+3,5,0,0,Math.PI*2);ctx.fill();if([0,1,2,5,6].includes(c.sp)){let h=20+size*47;ctx.fillStyle='#72563d';ctx.fillRect(x-3,y-h*.65,6,h*.65);ctx.fillStyle=c.sp===0?'#587448':'#315e3a';for(let j=0;j<5;j++){let ox=(j-2)*h*.16,oy=(j%2)*h*.15;ctx.beginPath();ctx.ellipse(x+ox,y-h*.72+oy,h*.24,h*.19,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#688b49';ctx.beginPath();ctx.ellipse(x-5,y-h*.85,h*.24,h*.13,0,0,Math.PI*2);ctx.fill()}else{ctx.strokeStyle='#416c38';ctx.lineWidth=2;for(let j=-2;j<=2;j++){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+j*4,y-8-Math.abs(j)*2);ctx.stroke()}}if(c.phase==='flor'||c.phase==='fruto'){ctx.fillStyle=c.phase==='flor'?'#efdfab':'#d38c4b';ctx.fillRect(x-7,y-11,3,3);ctx.fillRect(x+5,y-15,3,3)}}
function hero(){const wet=isWater(cell(p.x,p.y));let a=action&&ART.atlas[action.kind]?action.kind:wet?'swimPants':keys.size?(run?'run':'walk'):'idle';const seq=ART.atlas[a][p.dir]||ART.atlas[a].down;const i=action?Math.min(seq.length-1,Math.floor(action.time*seq.length)):Math.floor(p.t*(run?9:6))%seq.length;const f=seq[i],im=sprites[f.id],x=p.x-cam.x,y=p.y-cam.y,scale=.79;if(!wet){ctx.fillStyle='#14241c65';ctx.beginPath();ctx.ellipse(x,y,10,4,0,0,Math.PI*2);ctx.fill()}if(im?.complete&&im.naturalWidth){ctx.save();ctx.translate(Math.round(x),Math.round(y));if(f.mirror){ctx.scale(-1,1);ctx.drawImage(im,-(f.w-f.ax)*scale,-f.ay*scale,f.w*scale,f.h*scale)}else ctx.drawImage(im,-f.ax*scale,-f.ay*scale,f.w*scale,f.h*scale);ctx.restore()}}
function loop(t){let dt=Math.min(.05,(t-last)/1000||0);last=t;if(loaded){move(dt);if(auto){clock+=dt;if(clock>=12){clock=0;advance(1)}}draw();if(Math.floor(t/250)!==Math.floor((t-dt*1000)/250))refresh()}requestAnimationFrame(loop)}
for(const b of document.querySelectorAll('[data-dir]')){const d=b.dataset.dir;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(d)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(d)}const km={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'};addEventListener('keydown',e=>{if(km[e.key]&&!['SELECT','INPUT'].includes(e.target.tagName)){e.preventDefault();keys.add(km[e.key])}});addEventListener('keyup',e=>keys.delete(km[e.key]));addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());for(const b of document.querySelectorAll('[data-act]'))b.onclick=()=>perform(b.dataset.act);$('run').onclick=()=>{run=!run;refresh()};$('mode').onclick=()=>{auto=!auto;refresh()};$('dayNext').onclick=()=>advance(4);$('rest').onclick=rest;$('eat').onclick=eat;$('drink').onclick=drink;$('save').onclick=save;$('load').onclick=load;$('weather').onchange=()=>s.weather=$('weather').value;$('seed').innerHTML=Flora.species.map((a,i)=>`<option value="${i}">${a.name}</option>`).join('');
window.field={get s(){return s},get p(){return p},get action(){return action},get steps(){return steps},cell,target,perform,advance,move,commit,newWorld,save,load,rest,eat,setAuto(v){auto=v},keys};newWorld();loaded=true;requestAnimationFrame(loop);
